import SwiftUI

struct Button: View {
    enum Variant: String {
        case primary
        case secondary
        case ghost
    }

    enum Size: String {
        case sm
        case md
        case lg
    }

    var label: String
    var variant: Variant = .primary
    var size: Size = .md
    var disabled: Bool = false
    var loading: Bool = false
    var iconLeading: String? = nil

    var onPressed: (() -> Void)? = nil
    var onLongPressed: (() -> Void)? = nil

    var body: some View {
        VStack(spacing: 4) {
            if loading {
                ProgressView()
                    .accessibilityLabel("Loading")
            } else {
                HStack(spacing: 6) {
                    if let icon = iconLeading {
                        Image(systemName: icon)
                        Text("icon: \(icon)")
                    }
                    Text(label)
                }
            }
            Text("variant: \(variant.rawValue)")
            Text("size: \(size.rawValue)")
            Text("disabled: \(disabled ? "true" : "false")")
            Text("loading: \(loading ? "true" : "false")")
        }
        .padding(paddingForSize)
        .background(backgroundColor)
        .foregroundColor(foregroundColor)
        .opacity(disabled ? 0.5 : 1.0)
        .cornerRadius(8)
        .contentShape(Rectangle())
        .onTapGesture {
            guard !disabled, !loading else { return }
            onPressed?()
        }
        .onLongPressGesture {
            guard !disabled, !loading else { return }
            onLongPressed?()
        }
        .disabled(disabled || loading)
        .accessibilityLabel(Text(label))
        .accessibilityAddTraits(.isButton)
    }

    private var paddingForSize: CGFloat {
        switch size {
        case .sm: return 6
        case .md: return 10
        case .lg: return 14
        }
    }

    private var backgroundColor: Color {
        switch variant {
        case .primary: return .blue
        case .secondary: return .gray.opacity(0.2)
        case .ghost: return .clear
        }
    }

    private var foregroundColor: Color {
        switch variant {
        case .primary: return .white
        case .secondary: return .primary
        case .ghost: return .blue
        }
    }
}
